import sys
from collections import defaultdict

sys.setrecursionlimit(200000)

class Node:
    def __init__(self, data):
        self.data = data
        self.left = None
        self.right = None

def sumK(root, K):
    MOD = 10**9 + 7
    prefix_count = defaultdict(int)
    prefix_count[0] = 1

    def dfs(node, current_sum):
        if not node:
            return 0

        current_sum += node.data
        count = prefix_count[current_sum - K]

        prefix_count[current_sum] += 1

        left_count = dfs(node.left, current_sum)
        right_count = dfs(node.right, current_sum)

        prefix_count[current_sum] -= 1

        total = (count + left_count + right_count) % MOD
        return total

    return dfs(root, 0)

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)

    try:
        N = int(next(iterator))
        K = int(next(iterator))
    except StopIteration:
        return

    nodes = {}
    roots_candidate = set()

    if N > 0:
        for _ in range(N):
            try:
                val_str = next(iterator)
                left_str = next(iterator)
                right_str = next(iterator)

                val = int(val_str)
                node_id = val

                if node_id not in nodes:
                    nodes[node_id] = Node(val)
                else:
                    nodes[node_id].data = val

                if left_str != 'null':
                    left_val = int(left_str)
                    if left_val not in nodes:
                        nodes[left_val] = Node(left_val)
                    nodes[node_id].left = nodes[left_val]
                    roots_candidate.discard(left_val)
                else:
                    nodes[node_id].left = None

                if right_str != 'null':
                    right_val = int(right_str)
                    if right_val not in nodes:
                        nodes[right_val] = Node(right_val)
                    nodes[node_id].right = nodes[right_val]
                    roots_candidate.discard(right_val)
                else:
                    nodes[node_id].right = None

                roots_candidate.add(node_id)
            except StopIteration:
                break

    root = None
    if roots_candidate:
        root = nodes[list(roots_candidate)[0]]

    result = sumK(root, K)
    print(result)

if __name__ == "__main__":
    main()
